import { createSecureShare, openSecureShare, serializeSecureShare, parseSecureShare } from './secure-share.mjs';
import { deriveLocalVaultKey, encryptRecord, decryptRecord, encryptBytes, decryptBytes, putEncryptedRecord, getEncryptedRecords, deleteEncryptedRecord, MAX_FILE_BYTES } from './vault-store.mjs';
const DB = 'aegis-local-v1', STORE = 'identity', RECORD = 'primary';
let identity = null, section = 'overview', menuOpen = false, deviceRows = [], deviceBusy = false, deviceError = '', securityEvents = [], vaultRows = [], workRows = [], localDataBusy = false, localDataError = '';
let vaultKeyPromise = null;
const DEFAULT_API = 'https://aegis-backend-aume.onrender.com';
const apiUrl = () => (localStorage.getItem('aegis-api-url') || DEFAULT_API).replace(/\/$/, '');
const $ = (selector) => document.querySelector(selector);

function openDb() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Could not open local identity storage.'));
  });
}
async function getIdentity() {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const request = db.transaction(STORE, 'readonly').objectStore(STORE).get(RECORD);
    request.onsuccess = () => { resolve(request.result); db.close(); };
    request.onerror = () => { reject(request.error); db.close(); };
  });
}
async function saveIdentity(value) {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(value, RECORD);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error || new Error('Could not save identity.')); };
    tx.onabort = () => { db.close(); reject(tx.error || new Error('Identity storage transaction aborted.')); };
  });
}
async function createIdentity() {
  if (!crypto?.subtle || !indexedDB) throw new Error('This browser does not support the secure storage features AEGIS requires. Use a modern browser over HTTPS.');
  const signing = await crypto.subtle.generateKey({name:'ECDSA', namedCurve:'P-256'}, false, ['sign','verify']);
  const agreement = await crypto.subtle.generateKey({name:'ECDH', namedCurve:'P-256'}, false, ['deriveKey','deriveBits']);
  const pub = await crypto.subtle.exportKey('raw', signing.publicKey);
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', pub));
  const fingerprint = [...digest.slice(0,10)].map(n => n.toString(16).padStart(2,'0')).join('').toUpperCase();
  return { identityCode:`AEGIS-${fingerprint.match(/.{1,4}/g).join('-')}`, displayName:'', signingPublicKey:signing.publicKey, signingPrivateKey:signing.privateKey, agreementPublicKey:agreement.publicKey, agreementPrivateKey:agreement.privateKey, createdAt:new Date().toISOString() };
}
async function loadIdentity() { identity = await getIdentity(); if (!identity) { identity = await createIdentity(); await saveIdentity(identity); } }
